int main(void) {
    int n;
    scanf("%d", &n);

    int last[100001] = {0};
    int left = 1;
    int ans = 0;

    for (int i = 1; i <= n; i++) {
        int x;
        scanf("%d", &x);

        if (last[x] >= left) {
            left = last[x] + 1;
        }

        int len = i - left + 1;
        if (len > ans) {
            ans = len;
        }

        last[x] = i;
    }

    printf("%d\n", ans);
